export class Effects{constructor(machine){this.machine=machine;this.last=0;this.raf=0;}start(){const tick=t=>{if(t-this.last>120){this.machine.style.setProperty('--flicker',(0.97+Math.random()*.03).toFixed(3));this.last=t;}this.raf=requestAnimationFrame(tick)};this.raf=requestAnimationFrame(tick);}setPhase(p){this.machine.dataset.phase=p;}pulse(){this.machine.classList.add('impact');setTimeout(()=>this.machine.classList.remove('impact'),180);}}